/* scr_native.h -- glue between the lifted SCREAM jobs (scrA.c / scrB.c, generated by
 * winport/gen_scream_native.py) and the hybrid runner (winport/scream_native_rt.c).
 * This header is hand-written (not game-derived). See engine_fixes_v29_scream_native.py. */
#pragma once
#include "spu_context.h"

typedef void (*scr_fn)(spu_context*);
typedef struct { uint32_t addr; scr_fn fn; uint32_t label; } scr_ent_t;
typedef struct { const char* name; uint32_t lo, hi; uint64_t hash; const scr_ent_t* ents; unsigned n; } scr_job_t;
extern const scr_job_t g_scr_jobs[];
extern const unsigned g_scr_njobs;

/* != 0: the next lifted function to start resumes at this label (set by scr_ib / the runner). */
extern uint32_t g_scr_resume;

/* Interpreter-exact channel ops; a read that would stall bails AT pc (the interpreter parks). */
u128     scr_rdch(spu_context* ctx, uint32_t ch, uint32_t pc);
uint32_t scr_rchcnt(spu_context* ctx, uint32_t ch);
/* After the write: bail to `next` when an enabled event became pending with interrupts on. */
void     scr_wrch(spu_context* ctx, uint32_t ch, u128 v, uint32_t next);
/* Indirect branch to ctx->pc: C return / dispatch inside the job / bail to the interpreter. */
void     scr_ib(spu_context* ctx);
/* `bi $r0` function return (called right before the C `return`). */
void     scr_ret0(spu_context* ctx);
/* Hand the SPU back to the interpreter at pc (longjmp to the runner). */
__attribute__((noreturn)) void scr_bail(spu_context* ctx, uint32_t pc);

/* shufb for the hybrid code: SSSE3/SSE4.1 version of spu_helpers.h spu_shufb_ref (the x86 build of
 * the engine only has the scalar loop; it was ~15% of a core in the first native run). _u32[i]
 * holds big-endian word i as a host integer, so reversing the bytes of each 32-bit lane gives the
 * SPU byte order. Same selector precedence as the reference; checked against it by
 * scream_lift/test_scr_shufb.c. */
#if defined(__SSSE3__) && defined(__SSE4_1__)
#include <smmintrin.h>
static inline u128 scr_shufb(u128 a, u128 b, u128 c)
{
    const __m128i rev = _mm_setr_epi8(3, 2, 1, 0, 7, 6, 5, 4, 11, 10, 9, 8, 15, 14, 13, 12);
    __m128i A, B, S;
    memcpy(&A, &a, 16); memcpy(&B, &b, 16); memcpy(&S, &c, 16);
    A = _mm_shuffle_epi8(A, rev); B = _mm_shuffle_epi8(B, rev); S = _mm_shuffle_epi8(S, rev);
    const __m128i idx = _mm_and_si128(S, _mm_set1_epi8(0x1F));
    __m128i d = _mm_blendv_epi8(_mm_shuffle_epi8(A, idx), _mm_shuffle_epi8(B, idx),
                                _mm_cmpgt_epi8(idx, _mm_set1_epi8(15)));
    const __m128i hi2 = _mm_and_si128(S, _mm_set1_epi8((char)0xC0));
    const __m128i hi3 = _mm_and_si128(S, _mm_set1_epi8((char)0xE0));
    d = _mm_andnot_si128(_mm_cmpeq_epi8(hi2, _mm_set1_epi8((char)0x80)), d);
    d = _mm_or_si128(d, _mm_cmpeq_epi8(hi2, _mm_set1_epi8((char)0xC0)));
    d = _mm_blendv_epi8(d, _mm_set1_epi8((char)0x80), _mm_cmpeq_epi8(hi3, _mm_set1_epi8((char)0xE0)));
    d = _mm_shuffle_epi8(d, rev);
    u128 r;
    memcpy(&r, &d, 16);
    return r;
}
#else
#define scr_shufb spu_shufb
#endif
